warehouse_server = "<WAREHOUSE_SQL_ENDPOINT>"
workspace_id = "<WORKSPACE_ID>"
semantic_model_id = "<SEMANTIC_MODEL_ID>"
reconciliation_dax = 'EVALUATE\nSUMMARIZECOLUMNS(\n    DimDate[DateKey],\n    DimProgramType[ProgramTypeCode],\n    TREATAS({20250101,20250701,20251201},DimDate[DateKey]),\n    FILTER(VALUES(DimProgramType[ProgramTypeCode]),NOT ISBLANK(DimProgramType[ProgramTypeCode])),\n    "Households",[Households],\n    "HWC",[Households With Children],\n    "HWC_Elderly",CALCULATE([Elderly Households],FactHouseholdSnapshot[HouseholdType]="With children"),\n    "HWC_Disabled",CALCULATE([Disabled Households],FactHouseholdSnapshot[HouseholdType]="With children"),\n    "HWC_Workforce",CALCULATE([Workforce Households],FactHouseholdSnapshot[HouseholdType]="With children"),\n    "HWOC",[Households Without Children],\n    "HWOC_Elderly",CALCULATE([Elderly Households],FactHouseholdSnapshot[HouseholdType]="Without children"),\n    "HWOC_Disabled",CALCULATE([Disabled Households],FactHouseholdSnapshot[HouseholdType]="Without children"),\n    "HWOC_Workforce",CALCULATE([Workforce Households],FactHouseholdSnapshot[HouseholdType]="Without children"),\n    "AvailableUnits",[Available Units],\n    "TotalUnits",[Total Units],\n    "LIHTCUnits",[LIHTC Units],\n    "VacantUnits",[Vacant Units],\n    "VASH_HWC",[VASH With Children],\n    "VASH_HWOC",[VASH Without Children],\n    "OtherSupportive_HWC",[Other Supportive With Children],\n    "OtherSupportive_HWOC",[Other Supportive Without Children]\n)\nORDER BY DimDate[DateKey],DimProgramType[ProgramTypeCode]\n'
